def n3_poll_s(env: Optional[Mapping[str, str]] = None) -> float:
    blob = env if env is not None else os.environ
    raw = str(blob.get("FACTORY_N3_POLL_S") or "").strip()
    if raw:
        try:
            return max(0.0, float(raw))
        except ValueError:
            return DEFAULT_POLL_S
    return DEFAULT_POLL_S


