def input_schema_for(op: str, capability_id: str) -> Dict[str, Any]:
    properties: Dict[str, Any] = {{
        "capability_id": {{"type": "string"}},
        "idempotency_key": {{"type": "string"}},
        "id": {{"type": "integer"}},
        "q": {{"type": "string"}},
        "payload": {{"type": "object"}},
        "reason": {{"type": "string"}},
    }}
